import {resolveTakeClock,takeClockSources,formatTakeTimecode,parseTakeTimecode} from './take-clock.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function takeClockMarkup(value,fps,disabled=false){const clock=resolveTakeClock(value),lock=disabled?'disabled':'';return '<fieldset class="take-clock-fields"><legend>녹화 시계</legend><label>시간 기준<select data-take-clock="source" '+lock+'>'+takeClockSources.map(([key,label])=>'<option value="'+key+'" '+(key===clock.source?'selected':'')+'>'+label+'</option>').join('')+'</select></label><label>시작 타임코드<input aria-label="시작 타임코드" data-take-clock="timecode" value="'+esc(formatTakeTimecode(clock.startFrame,fps))+'" '+lock+' spellcheck="false" placeholder="00:00:00:00"></label></fieldset>';}
export function takeClockInput(input,current,fps){if(!input.dataset.takeClock)return null;const next=resolveTakeClock(current);if(input.dataset.takeClock==='source')next.source=input.value;else if(input.dataset.takeClock==='timecode')next.startFrame=parseTakeTimecode(input.value,fps);else throw Error('녹화 시계 필드를 확인하세요.');return resolveTakeClock(next);}
